# -*- coding: utf-8 -*-
"""English translations, batch 13 (40 figures)."""
EN = {
"以利以谢（摩西之子）": dict(lesson="Remember God is my help",
 summary="Moses' second son, his name meaning 'God is my help.'",
 witness="Eliezer was Moses' second son, his name meaning 'the God of my father was my help and delivered me from Pharaoh's sword.' With his son's name Moses carved God's deliverance into the family's memory. A name is itself a witness—reminding posterity: God is our help.",
 follow=["Commemorating God's deliverance and help in a concrete way","Passing God's works on to the next generation"],
 caution=["Not forgetting how God once rescued you"],
 applications=["Commemorate God's help in some way (a name, a marker, a record)","Often tell your children of God's deliverance in your life","In new troubles remember 'God is my help'"],
 prayer="Lord, Eliezer's name declares You are help. Make me ever remember Your deliverance, pass Your works to the next generation, and firmly trust You are my help in trouble. Amen."),
"亚比户": dict(lesson="To serve God, it must be by what God ordained",
 summary="Aaron's second son, struck down by God with Nadab for offering strange fire.",
 witness="Abihu was Aaron's second son, having the honor of priesthood, yet with his brother Nadab offered strange fire the LORD had not commanded, and was consumed by fire on the spot. God said: among those who come near Me I will be shown holy. The nearer the service to God, the less one may act by one's own will.",
 follow=[],
 caution=["Not altering the way of service God ordained by one's own will","Not slighting God's holiness because of one's honored status","Not treating spiritual service as a routine to improvise freely"],
 applications=["Before serving, first ask: is this what God commanded, or something I thought up?","Draw near to God with reverence, not slighting holy things","Respect the order God established in church service"],
 prayer="Lord, Nadab and Abihu were destroyed for offering strange fire. Make me serve You with reverence, doing all by what You ordained, not acting on my own will in holy things. Amen."),
"以利亚撒（亚伦之子）": dict(lesson="Faithfully taking up, steadily carrying the baton",
 summary="Aaron's son, who succeeded as high priest and divided the land with Joshua.",
 witness="Eleazar was Aaron's son who, after his two elder brothers were destroyed by strange fire, faithfully took up the office of high priest and divided the land for Israel with Joshua. Unassuming, he yet steadied the priestly system in a key transition, passing the holy office down generation by generation.",
 follow=["Faithfully taking up the office entrusted after a predecessor's departure","Working together of one heart with a co-worker (Joshua), each doing his part","Steadying the ministry amid transition and turmoil"],
 caution=["Not shrinking back because of another's failure"],
 applications=["At a handover or transition, willingly take up the responsibility you ought to bear","Learn to work of one heart with people in different posts","Value passing on the faith and the ministry"],
 prayer="Lord, Eleazar faithfully took up the office of high priest. Make me faithful and steady in what's entrusted, of one heart with co-workers, passing on Your work well. Amen."),
"以他玛": dict(lesson="Quietly doing your duty within the system",
 summary="Aaron's son, a branch of the priestly family.",
 witness="Ithamar was Aaron's youngest son, managing the Levites' work and the furnishings in the tabernacle service, his descendants also becoming a branch of the priestly family. Not a figure in the spotlight, he was yet faithful in the details, keeping the sanctuary's service orderly.",
 follow=["Faithfully fulfilling duty in detailed tasks","Valuing the worth of behind-the-scenes management and service"],
 caution=["Not despising the inconspicuous yet necessary duty"],
 applications=["Willingly do behind-the-scenes management and coordination in the team","Do the tedious but necessary things well","Trust God remembers those who quietly do their duty"],
 prayer="Lord, Ithamar quietly managed and faithfully did his duty in the tabernacle. Make me too faithful in an inconspicuous post, keeping what You entrust orderly. Amen."),
"昂": dict(lesson="Following the wrong person, drawn into rebellion",
 summary="A man of the tribe of Reuben, one of Korah's faction.",
 witness="On was a man of the tribe of Reuben, listed among Korah's faction who rose against Moses and Aaron. He was drawn into a rebellion questioning the leaders God had established, joining Korah, Dathan, and Abiram. Following wrong leaders and taking part in rebellion is exceedingly dangerous.",
 follow=[],
 caution=["Following rebellious leaders, drawn into rebellion","Questioning and attacking the authority God established"],
 applications=["Be careful whom and what stance you follow and echo","Don't lightly get drawn into questioning and attacking the authority God established","Keep discernment amid group agitation, withdraw early"],
 prayer="Lord, On followed Korah and was drawn into rebellion. Give me discernment, not to echo rebellion or attack the authority You established, but keep a heart fearing You amid agitation. Amen."),
"巴勒": dict(lesson="Trying to curse what God has blessed is finally in vain",
 summary="King of Moab, who hired Balaam to curse Israel.",
 witness="Balak was king of Moab who, fearing Israel, hired the magician Balaam at great cost to curse them. But God forbade it, and Balaam's mouth instead spoke blessing. Balak repeatedly changed locations and raised the price, trying to buy a curse, but could not stop God's blessing on His people.",
 follow=[],
 caution=["Trying to oppose God's will by schemes is futile","Out of fear, plotting to curse and harm others","Thinking rich rewards can move spiritual outcomes"],
 applications=["Don't secretly plot to harm or curse others out of fear of them","Remember no one can remove God's blessing","When threatened, look to God, not counter with schemes"],
 prayer="Lord, Balak tried to curse Your blessed people, and was finally in vain. Make me not plot against others out of fear, firmly trusting no one can rob Your blessing, resting in You. Amen."),
"西罗非哈": dict(lesson="A father without sons left daughters who guarded the inheritance",
 summary="A man of the tribe of Manasseh, without sons, whose five daughters secured the inheritance.",
 witness="Zelophehad was a man of the tribe of Manasseh who died in the wilderness with no sons, only five daughters. Though sonless, his daughters argued their case and obtained the inheritance, and through this God set a statute that daughters could inherit. A man 'without heirs' became the occasion for a just statute.",
 follow=["Leaving behind descendants who trust God even amid lack"],
 caution=["Not despairing for lack of a 'son' (the traditional hope)"],
 applications=["Still trust God's arrangement amid life's lack","Value the worth and rights of daughters (often the overlooked)","Trust God can bring justice and blessing out of your lack"],
 prayer="Lord, though Zelophehad had no son, through his daughters You set a just statute. Make me still trust You amid lack, knowing You can bring blessing out of insufficiency. Amen."),
"玛拉（西罗非哈之女）": dict(lesson="Bravely inquire for legitimate rights",
 summary="One of Zelophehad's daughters.",
 witness="Mahlah was Zelophehad's eldest daughter, who with her four sisters stood before Moses, the priest, and the whole congregation to claim their father's inheritance: our father died with no son; why should his name be taken away because he had no son? They inquired with reasoned argument, and God granted it.",
 follow=["Inquiring with reasoned argument for legitimate rights","Sisters of one heart, bravely standing forth"],
 caution=["Inquire with reverence, not striving and making a scene"],
 applications=["Express legitimate, reasonable rights bravely and appropriately","Argue your case through lawful channels","Trust God hears reasoned, reverent inquiry"],
 prayer="Lord, Mahlah and her sisters inquired bravely, and You granted it. Give me courage to express and inquire appropriately for what is right, trusting Your granting. Amen."),
"挪阿": dict(lesson="Striving of one heart, blessed together",
 summary="One of Zelophehad's daughters.",
 witness="Noah was one of Zelophehad's daughters, who with her sisters inquired of one heart for the inheritance and were granted it together by God. They did not each shrink back, but stood forth of one heart, and as a result not only gained their family's inheritance but set a precedent for daughters of sonless families in later ages.",
 follow=["Sisters standing and striving of one heart","Becoming a precedent of blessing for later generations"],
 caution=["Not each shrinking back, not passing the buck to one another"],
 applications=["Face what should be striven for of one heart with companions","Support one another and not shrink back in appropriate matters","Trust God hears the inquiry of those of one heart"],
 prayer="Lord, Noah and her sisters of one heart were granted by You together. Make me face what should be striven for of one heart with others, not shrinking or passing the buck, trusting Your granting. Amen."),
"曷拉": dict(lesson="Guarding the inheritance you ought to have",
 summary="One of Zelophehad's daughters.",
 witness="Hoglah was one of Zelophehad's daughters. She and her sisters later, at God's command, married within their own tribe, so the inheritance they received would not pass away from their tribe. They both boldly strove and obeyed the boundary God set, keeping the inheritance steadily within the tribe.",
 follow=["Both boldly striving and obeying the boundary God set","Keeping the inheritance received from being lost"],
 caution=["What is won must also be kept according to God's command"],
 applications=["Strive for what you ought to have, and also obey God's rules","Keep the inheritance God gives (gifts, responsibilities) from being lost","Hold the balance between freedom and obedience"],
 prayer="Lord, Hoglah both strove for the inheritance and obeyed Your boundary to keep it. Make me both bold to receive Your gifts and careful to keep them by Your command, not losing them. Amen."),
"密迦（西罗非哈之女）": dict(lesson="An ordinary woman, recorded in the statute",
 summary="One of Zelophehad's daughters.",
 witness="Milcah was one of Zelophehad's daughters. She and her sisters' names are each recorded in Scripture, because their inquiry brought about the statute of 'daughters inheriting.' A few ordinary women's courage and reason became an institution affecting later ages.",
 follow=["Bringing long-term benefit by a reasonable appeal"],
 caution=["Not despising the long-term impact of one appropriate action"],
 applications=["Trust one reasonable appeal can benefit many","God can use courage in small things for great things","Value the meaning of fairness and institution for posterity"],
 prayer="Lord, the reasonable appeal of Milcah and her sisters became a statute affecting later ages. Make me brave in what is appropriate, trusting You can benefit many through a small action. Amen."),
"得撒": dict(lesson="A name remembered by God",
 summary="One of Zelophehad's daughters.",
 witness="Tirzah was Zelophehad's youngest daughter. She and her sisters' names appear repeatedly in Numbers and Joshua. They may be ordinary, but God recorded their names again and again—in God's eyes no one who faithfully inquires and acts reasonably is forgotten.",
 follow=["Acting faithfully and reasonably, not seeking people's remembrance"],
 caution=["Not thinking, because you are ordinary, that you are unseen by God"],
 applications=["Trust God remembers everyone who acts faithfully","Not to be remembered by people, only to be remembered by God","Hold justice and courage amid ordinariness"],
 prayer="Lord, You recorded the names of Tirzah and her sisters again and again. Make me act faithfully and reasonably, not seeking people's praise, only to be remembered by You in eternity. Amen."),
"亚干": dict(lesson="Secret greed implicates the whole community",
 summary="Who by secretly taking devoted things caused Israel's defeat at Ai.",
 witness="Achan, at the capture of Jericho, disobeyed God's command and secretly took devoted goods, hiding them in his tent. As a result Israel was routed at tiny Ai, with thirty-six men killed. One man's secret greed implicated the whole community—sin is never merely a 'private matter.'",
 follow=[],
 caution=["Secretly coveting what God forbade, thinking no one knew","One person's hidden sin implicating the whole community"],
 applications=["Don't secretly covet what you shouldn't have; God sees all","Understand your personal sin can affect the whole community","Confess sin in time, not hiding it in the 'tent'"],
 prayer="Lord, Achan's secret greed implicated the whole camp. Shine on the hidden greed in me, that I take no unjust gain, knowing my choices concern the community, and confess to You in time. Amen."),
"迦米": dict(lesson="A link between the generations",
 summary="Achan's father.",
 witness="Carmi was Zabdi's son and Achan's father, a member of the family of Zerah. He is a link connecting his father Zabdi to his son Achan, his name recorded along with Achan's incident. On the family chain, each link receives from one and passes to the next, and each bears influence.",
 follow=["Doing one's part in the chain of generations"],
 caution=["The previous generation's influence passes to the next; be careful"],
 applications=["Be aware of your responsibility to pass on in the family chain","Strive to pass good influence, not sin, to the next generation","Pray to break the cycle of sin in the family"],
 prayer="Lord, Carmi was between the generations. Make me do my part in the family chain, passing on the influence of fearing You, breaking the cycle of sin and curse by Your power. Amen."),
"撒底": dict(lesson="A family head with far-reaching influence",
 summary="Achan's grandfather.",
 witness="Zabdi was Achan's grandfather, a member of the family of Zerah. When Achan sinned and was judged, Scripture traced back all the way to Zabdi's line. The ancestor's name and the descendant's deeds are recorded together—reminding us the family's root and the choices of each generation are connected.",
 follow=["Valuing the responsibility of laying a godly foundation for the family"],
 caution=["The family's influence extends to descendants; be careful"],
 applications=["Value your influence as a family member on descendants","Lay a foundation of fearing God for the family","Understand root and fruit are connected across generations"],
 prayer="Lord, Zabdi's line was recorded together with Achan's sin. Make me lay a foundation of fearing You for the family, knowing today's choices affect descendants. Amen."),
"亚多尼洗德": dict(lesson="Allying to resist God must fail",
 summary="King of Jerusalem, head of the coalition of five southern kings.",
 witness="Adoni-zedek was king of Jerusalem who gathered a coalition of five southern kings to attack Gibeon, which had made a covenant with Israel. Joshua marched swiftly, and God sent great hailstones and made the sun stand still; the five kings fled and hid in a cave, and were finally captured and killed. However great the alliance, resisting God's will finally collapses.",
 follow=[],
 caution=["Forming a faction and alliance to resist God's work","Becoming hostile and ganging up because others turn to God"],
 applications=["Don't ally with others to resist what God is doing","When others turn to God, rejoice for them rather than be hostile","Remember numbers and force cannot overcome God's will"],
 prayer="Lord, Adoni-zedek allied to resist You, and was finally crushed. Make me not conspire with others against Your work, gladly see people turn to You, and obey Your will. Amen."),
"何咸": dict(lesson="Doing evil with the crowd, sharing the responsibility",
 summary="King of Hebron, a member of the southern coalition.",
 witness="Hoham was king of Hebron, a member of the coalition of five southern kings, who with the king of Jerusalem attacked Gibeon and resisted Israel, and finally perished with the other kings. His end reminds us: following the crowd into the camp resisting God does not exempt one from responsibility because of 'numbers.'",
 follow=[],
 caution=["Joining an alliance with the crowd, drawn into action resisting God","Thinking the law won't punish the many, doing evil with the crowd"],
 applications=["Don't join the wrong camp just because 'everyone is doing it'","Discern right and wrong even under group pressure","Take responsibility for your choices, not hiding in the crowd"],
 prayer="Lord, Hoham perished resisting Your people with the crowd. Give me courage to discern under group pressure, not doing evil with the crowd, following You alone. Amen."),
"毗兰": dict(lesson="An ally in evil, finally judged",
 summary="King of Jarmuth, a member of the southern coalition.",
 witness="Piram was king of Jarmuth, one of the coalition of five southern kings, who joined in attacking Gibeon and opposing God, and was finally captured and killed by Joshua at the cave mouth with the other kings. However large the alliance, it only walked together toward the same judgment.",
 follow=[],
 caution=["Allying with others to attack what God would preserve","Resisting God by relying on the alliance's momentum"],
 applications=["Before choosing an alliance, see whether what it opposes is God's will","Don't be carried away by the 'momentum of an alliance'","Withdraw early from the camp resisting God"],
 prayer="Lord, Piram was judged for allying to resist You. Make me careful in the alliances I form, not consorting with forces resisting You, but standing on Your side alone. Amen."),
"雅非亚": dict(lesson="However high the position, one cannot stand firm",
 summary="King of Lachish, a member of the southern coalition.",
 witness="Japhia was king of Lachish, a member of the southern coalition, who joined the war attacking Gibeon and resisting Israel, hidden, captured, and killed with the other kings. A city king's position, when at enmity with God, is also vulnerable.",
 follow=[],
 caution=["Relying on position, drawn into war resisting God","Going with the crowd of kings to shared destruction"],
 applications=["Don't let status and power put you on God's opposite side","Examine what and whom you are loyal to and join","Remember position cannot save a life before God"],
 prayer="Lord, Japhia relied on royal power to resist You and was finally destroyed. Make me not rely on status, careful about what I am loyal to, fearing You alone. Amen."),
"底璧王": dict(lesson="Better to turn back of one heart than to do evil of one heart",
 summary="King of Eglon, a member of the southern coalition.",
 witness="The king of Debir was the king of Eglon, the last member of the coalition of five southern kings, who allied to attack Gibeon and resist Israel, hid in a cave together and was executed together. The five kings could each have turned back, but chose to do evil of one heart, and got the same end.",
 follow=[],
 caution=["Of one heart with others, but of one heart in the wrong thing","Missing the chance to each turn back"],
 applications=["Use 'one heart' for turning back and doing good, not for evil","When the group goes astray, be the one who turns back","Don't wait until you fall into the same end with everyone to wake up"],
 prayer="Lord, the king of Debir did evil of one heart with the kings and perished together. Make me use one heart for fearing You and doing good, bravely turning back when the group goes astray. Amen."),
"耶宾（夏琐王）": dict(lesson="The northern overlord too is no match for God",
 summary="King of Hazor, head of the northern coalition, defeated by Joshua.",
 witness="Jabin was king of Hazor, who rallied the northern kings with many chariots and horses to wipe out Israel. Joshua triumphed by God and burned Hazor, the overlord city of the time. The strongest military alliance is but dust to be swept away before God.",
 follow=[],
 caution=["Relying on military force and alliance, thinking himself invincible","Massing forces to resist God's people"],
 applications=["Don't be frightened by the momentum of the powerful; God is greater","Don't put your faith in 'chariots and horses' (might)","Remember the strongest city will topple before God"],
 prayer="Lord, Jabin king of Hazor massed a strong army to resist You and was swept away. Make me not fear the powerful nor rely on force, but rely only on You who makes armies retreat. Amen."),
"基遍人长老": dict(lesson="Seeking survival by a ruse, God still treats with mercy",
 summary="Leaders of the inhabitants of Gibeon, who by a ruse made a covenant with Israel.",
 witness="The elders of Gibeon, hearing of Israel's victories, in fear disguised themselves as travelers from afar, deceiving Israel into a covenant with moldy bread and worn wineskins. When the ruse was exposed, they became servants 'cutting wood and drawing water,' yet by the covenant they survived, and were even cared for by God in David's time. Though a survival ruse is not honorable, God's mercy still left room.",
 follow=["Seeking reconciliation with God's people when the powerful drew near (though by a ruse)","After the covenant, willingly keeping a lowly duty"],
 caution=["Seeking a way to live by deceit and ruse"],
 applications=["When seeking survival and a way out, choose honesty over deceit","Even if you once used the wrong method, you can survive and be shown grace in lowliness","See that God's mercy reaches even 'outsiders who used a ruse'"],
 prayer="Lord, the Gibeonites sought survival by a ruse, yet You treated them with mercy. Make me seek a way out by honesty not deceit, and let me see the breadth of Your mercy. Amen."),
"西西拉": dict(lesson="However strong the iron chariots, they cannot beat God's appointed time",
 summary="A Canaanite general, killed by Jael with a tent peg.",
 witness="Sisera was the commander of Jabin king of Hazor, with nine hundred iron chariots, who oppressed Israel for twenty years. Deborah and Barak went to battle by God's word, and God routed his whole army; the fleeing Sisera finally died under the tent peg of a woman, Jael. The end of the mighty is often unexpected.",
 follow=[],
 caution=["Oppressing by force, bullying the weak","Relying on the advantage of 'iron chariots,' with no regard for God"],
 applications=["Don't use your advantage to suppress others","Remember even the strongest force has an end God appoints","Don't despise what God accomplishes through the seemingly weak"],
 prayer="Lord, Sisera's iron chariots could not beat the time You appointed. Make me not rely on strength to bully people, nor fear oppression, trusting You will avenge the oppressed. Amen."),
"伊矶伦": dict(lesson="Coveting domination, finally judged",
 summary="King of Moab, assassinated by Ehud.",
 witness="Eglon was king of Moab who, while Israel sinned, dominated them for eighteen years, living in luxury, fat and at ease. God raised up the left-handed Ehud, who ended this oppressor with a double-edged sword. Hegemony in ease, God does not tolerate forever.",
 follow=[],
 caution=["Dominating and extorting people while they are weak","Losing vigilance amid oppression and ease"],
 applications=["Don't take advantage of people's peril to dominate and exploit","Beware ease making one numb and disregarding God","Pray for and help those oppressed by the powerful"],
 prayer="Lord, Eglon dominated Your people and was finally judged. Make me not oppress people nor grow numb in ease, remembering You will require the sin of oppressors. Amen."),
"耶宾（士师时代）": dict(lesson="Long oppression—God will surely raise up deliverance",
 summary="King of Hazor who oppressed Israel for twenty years, the enemy in Deborah's time.",
 witness="In the time of the judges, Jabin king of Hazor oppressed Israel for twenty years with iron chariots and a strong army, making the people cry out in distress. God then raised up the prophetess Deborah and Barak, who utterly cut off Jabin's power. However long the oppression, there is an end God appoints.",
 follow=[],
 caution=["Long oppressing by force, thinking himself secure","Not knowing that the longer the oppression, the nearer the judgment"],
 applications=["Don't think you can suppress people long by force","Cry to God amid oppression","Trust God hears the cry of the afflicted and will raise up deliverance"],
 prayer="Lord, Jabin oppressed Your people twenty years, yet You finally raised up deliverance. Comfort the oppressed, and make me not bully people by force, but fear You alone. Amen."),
"西巴（米甸王）": dict(lesson="The plunderer is finally called to account",
 summary="One of the two kings of Midian, pursued and killed by Gideon.",
 witness="Zebah was a king of Midian who with Zalmunna invaded year after year and plundered Israel's produce, driving the people to hide in caves. God pursued and killed him through Gideon's three hundred. The one who lives by plundering others, God Himself calls to account.",
 follow=[],
 caution=["Profiting by plundering and exploiting others","Oppressing people into poverty and fear"],
 applications=["Don't fulfill yourself by seizing from others","Pray for those exploited and oppressed","Trust God watches over the plundered and will avenge injustice"],
 prayer="Lord, Zebah king of Midian plundered Your people and was finally called to account. Make me not profit by exploitation, and watch over all who are oppressed and plundered. Amen."),
"撒慕拿": dict(lesson="Walking with evil, perishing together",
 summary="One of the two kings of Midian, killed by Gideon.",
 witness="Zalmunna was a king of Midian with Zebah, who together invaded year after year and plundered Israel, and were caught and killed together by Gideon. The two kings abetted each other in evil, and bore the punishment together. Doing evil together is but receiving judgment together.",
 follow=[],
 caution=["Abetting evil with others, allied to oppress people","Thinking numbers and force can escape accountability"],
 applications=["Don't ally with others to oppress and plunder","When choosing companions, look at the direction they walk","Remember accomplices in evil also share the consequences"],
 prayer="Lord, Zalmunna and Zebah did evil and perished together. Make me stay far from accomplices in evil, walking with those who fear You, on the road of blessing. Amen."),
"俄立": dict(lesson="The plunderer's end is carved into a place name",
 summary="A Midianite leader, killed by Gideon's army.",
 witness="Oreb was one of the leaders of Midian, killed at a rock in Gideon's pursuit, and that place was afterward called 'the rock of Oreb.' He came with the Midianite host to plunder Israel, and finally even his name became a memorial of defeat. The end of those who oppress by force is recorded by God.",
 follow=[],
 caution=["Plundering and oppressing with the powerful side","Thinking numbers and force let one run rampant"],
 applications=["Don't join the side that oppresses and plunders","Remember the end of oppressors is all in God's remembrance","Keep a heart fearing God even before power"],
 prayer="Lord, Oreb plundered with Midian and finally perished leaving his name. Make me not bully people by force, knowing the end of all oppressors is in Your hand. Amen."),
"西伊伯": dict(lesson="Keeping company with evil, buried in one place",
 summary="A Midianite leader, killed with Oreb.",
 witness="Zeeb was a leader of Midian, captured and killed with Oreb by Gideon's army, the place of his death afterward called 'the winepress of Zeeb.' He walked with Oreb in plundering and was annihilated together. Even the end of those who do evil together is recorded in one place.",
 follow=[],
 caution=["Walking with others in evil and plunder","Thinking many accomplices can escape judgment"],
 applications=["Be careful whom and what direction you walk with","Don't consort with oppressors","Remember accomplices in evil also share the end"],
 prayer="Lord, Zeeb walked with Oreb in plunder and was annihilated together. Make me stay far from accomplices in evil, walking with those who fear You, on the road of blessing. Amen."),
"玛挪亚的妻子": dict(lesson="Receiving the promise, with faith steadier than her husband's",
 summary="Samson's mother, foretold by an angel that she would bear a son.",
 witness="She was Samson's mother, originally barren, to whom the Angel of God appeared, foretelling she would bear a Nazirite. When her husband Manoah was terrified, 'we shall surely die, for we have seen God,' she calmly said: if the LORD meant to kill us, He would not have accepted our offering. She steadied her panicked husband with faith.",
 follow=["Steadying panicked family with faith and reason","Taking seriously the calling and charge God gave"],
 caution=["Not letting momentary terror rob your faith"],
 applications=["When family panic, be the one with faith who steadies","Take seriously God's calling on your children","Face spiritual experiences with reasoned faith"],
 prayer="Lord, Manoah's wife steadied her panicked husband with faith. Give me such steady faith, bringing calm when family fear, soberly receiving Your charge. Amen."),
"参孙的非利士妻": dict(lesson="A marriage treated as a bargaining chip sows tragedy",
 summary="A woman of Timnah, Samson's first wife.",
 witness="She was a Philistine woman of Timnah, Samson's first wife. Under threat from thirty companions she pressed Samson for the answer to his riddle, was then given by her father to another man, and finally was burned to death in the conflict. Caught between the feuds of two peoples, she became a victim of that tragedy.",
 follow=[],
 caution=["(A warning under coercion) selling out a loved one's secret under pressure","Drawn into the whirlpool of mutual revenge and feud"],
 applications=["Don't sell out one who trusts you under pressure","Beware treating marriage and relationships as bargaining chips for gain","Intercede for those caught amid hatred and conflict"],
 prayer="Lord, Samson's wife was drawn into a feud and became a victim. Make me not sell out trust under coercion, and have mercy on all caught and harmed amid hatred and conflict. Amen."),
"但支派探子": dict(lesson="For themselves, they seized another's idol",
 summary="The five men the tribe of Dan sent, who seized Micah's idol.",
 witness="The tribe of Dan sent five spies to find a place to live, and on the way seized Micah's idol and his priest, moving to Laish and setting up their own idol worship. They sought land and 'gods' for the tribe, but by seizure and idolatry. Apart from God's word, 'developing for oneself' took a crooked road.",
 follow=[],
 caution=["Seizing others' things for one's own benefit","Setting up idol worship of one's own, forsaking the true God","Drifting with the tide in an age when 'everyone did as he saw fit'"],
 applications=["When seeking development, don't use seizure or injustice as means","Don't set up any 'idol' for yourself to replace the true God","Amid a drifting trend, still take God's word as the standard"],
 prayer="Lord, the tribe of Dan sought development by seizure and idols, taking a crooked road. Make me, in seeking a way out, not seize others' things or worship idols, taking Your word as the standard in all things. Amen."),
"以利加拿": dict(lesson="Keeping the habit of worship with the family",
 summary="Hannah's husband, Samuel's father.",
 witness="Elkanah was Samuel's father, who went up to Shiloh on schedule each year to worship and sacrifice, and loved Hannah who suffered from barrenness. In a chaotic age of the judges, he quietly maintained a God-fearing home—Samuel was offered to God and raised up by God in such a home.",
 follow=["Worshipping God on schedule, maintaining the family's spiritual habit","Considerate of and comforting a suffering family member"],
 caution=["When there is strife at home, more actively maintain harmony"],
 applications=["Establish a fixed rhythm for the whole family to worship and draw near to God","Give considerate love when a spouse or family member suffers","Trust God will use a God-fearing home"],
 prayer="Lord, Elkanah maintained a God-fearing home in a chaotic age and raised Samuel. Help me keep the family's worship, be considerate of those I love, and place my home in Your hands. Amen."),
"毗尼拿": dict(lesson="Using what you have to wound another's pain",
 summary="Elkanah's other wife, who often provoked Hannah.",
 witness="Peninnah was Elkanah's other wife, with sons and daughters. Because Hannah was barren, year after year she 'was her rival, provoking her severely, to irritate her.' She used what she had (children) to wound Hannah's deepest pain. To harm another's lack with your own advantage is utterly cruel.",
 follow=[],
 caution=["Using your advantage to wound another's lack","Provoking and irritating those around you with words"],
 applications=["Don't use what you have to wound another's lack","Have more compassion for those near you who have lack and pain","Restrain a tongue that provokes and irritates"],
 prayer="Lord, Peninnah used her children to wound Hannah. Remove from me the heart that wounds people with advantage, make me compassionate to others' lack, treating people with kindness, not provocation. Amen."),
"何弗尼": dict(lesson="Holy office without fear invites judgment",
 summary="One of Eli's wicked sons, who despised the LORD's offerings.",
 witness="Hophni was a son of the priest Eli, who as a priest despised the LORD's offerings, took the offerings by force, behaved corruptly, and made the people loathe sacrificing. He did not know the LORD, and finally died with his brother on the day the ark was captured. Wearing holy office without fear is most dangerous.",
 follow=[],
 caution=["In holy office yet without fear in the heart","Using office to line his pockets and indulge lust","Making others loathe God because of himself"],
 applications=["In serving, often examine whether you truly know and fear God","Don't use a spiritual identity for private gain","Beware that your behavior can trip up others"],
 prayer="Lord, Hophni was a priest yet without fear, and invited judgment. Cleanse my heart in service, that I truly know and fear You, and not by me make people turn from You. Amen."),
"非尼哈（以利之子）": dict(lesson="Treating the holy as a game, glory will depart",
 summary="Eli's wicked son, who died in battle with the ark.",
 witness="Phinehas was Eli's wicked son, who with Hophni profaned the priesthood. They carried the ark to the battlefield as a war talisman, and as a result the ark was captured and the brothers died together. His posthumous son was named 'Ichabod'—the glory has departed from Israel.",
 follow=[],
 caution=["Treating holy things as a tool or talisman","Sinning knowingly, not heeding his father's and God's warning"],
 applications=["Don't treat faith as a tool to achieve ends","Treat holy things with a reverent heart","Take admonition to heart, turning back early"],
 prayer="Lord, Phinehas treated the ark as a talisman and brought the departure of glory. Make me treat Your holy things with reverence, not faith as a tool, lest I lose Your presence. Amen."),
"以迦博": dict(lesson="The moment glory departed, carved into a name",
 summary="Phinehas' son, his name meaning the glory has departed from Israel.",
 witness="Ichabod was Phinehas' posthumous son. When the news came that the ark was captured and his grandfather Eli and father died the same day, his mother died in childbirth and named him 'Ichabod,' meaning 'the glory has departed from Israel.' From birth he bore the mark of an age's spiritual desolation.",
 follow=[],
 caution=["(An age's warning) how tragic that God's glory departed because of rebellion","An age that treats the holy as a game finally loses His presence"],
 applications=["Count the loss of God's presence the greatest tragedy, and strive to recover it","Don't let 'Ichabod' (glory departed) be the picture of your home","Often examine: is God's presence still among us?"],
 prayer="Lord, 'Ichabod' declared the departure of glory. Make me count the loss of Your presence the most painful, and strive to recover it, that the mark of desolation not fall on me and my home. Amen."),
"基士": dict(lesson="The errand to find donkeys leads to the start of a kingdom",
 summary="A Benjamite, Saul's father.",
 witness="Kish was a Benjamite, Saul's father. He sent his son to find the lost donkeys, and this ordinary errand led Saul to meet Samuel and be anointed Israel's first king. God often unfolds His grand plan through the most ordinary daily errands.",
 follow=["Doing his duty in an ordinary household errand"],
 caution=[],
 applications=["Faithfully do the ordinary errand at hand; God's plan is often hidden in it","Don't despise the spiritual potential of small daily things","Trust God can unfold a great plan through a small thing like 'finding donkeys'"],
 prayer="Lord, Kish sent Saul to find donkeys, and it led to the start of a kingdom. Make me faithfully do the ordinary thing at hand, trusting You can unfold Your grand plan through daily small things. Amen."),
"亚比拿达（扫罗之子）": dict(lesson="Falling together with the family's fate",
 summary="A son of Saul, who died with his father at Gilboa.",
 witness="Abinadab was a son of Saul, who died in the battle on Mount Gilboa with his father and brothers Malchi-shua and Jonathan. He fell together with the decline of Saul's house. A person's fate is often tightly bound to the rise and fall of the family he belongs to.",
 follow=[],
 caution=["(Background) the decline of a family that rebels against God reaches the descendants"],
 applications=["Be aware that the family's spiritual direction concerns the whole household","Ask God's mercy and turning for your own family","Don't let the family's rebellion continue to the next generation"],
 prayer="Lord, Abinadab fell with Saul's house. Have mercy on my family, that we turn to You and walk in the way of blessing, not letting rebellion reach descendants. Amen."),
"麦基舒亚": dict(lesson="Going to the end with the father's house",
 summary="A son of Saul, who died in battle on Mount Gilboa.",
 witness="Malchi-shua was a son of Saul, who fell in the battle on Mount Gilboa with his father Saul and brothers Jonathan and Abinadab. He fell together with the defeat of Saul's house. Children's fate is often tightly bound to the father's house's spiritual direction—this is exactly the reason to pray for the family and ask for its turning.",
 follow=[],
 caution=["(Background) the decline of a father's house that rebels against God reaches the children"],
 applications=["Watch and pray for your own family's spiritual direction","Don't let the elders' rebellion continue into the whole family's decline","Be the one in the family who turns to God"],
 prayer="Lord, Malchi-shua fell with Saul's house. Have mercy on my family, make us turn to You, not letting rebellion reach the children, and let me be the one in the family who turns to You. Amen."),
}
